frappe.web_form.after_load = () => {
    if (window.location.pathname.endsWith("/new") && frappe.session.user) {
        let current_path = window.location.href;
        window.location.href = current_path.replace("/new", "/" + frappe.session.user);
    }
}

$(document).ready(function () {

    // =========================================================================
    //  CONFIG
    // =========================================================================

    var DRAFT_KEY_PREFIX = 'fle_draft_v4_';

    // =========================================================================
    //  INJECT WEBFORM STYLES
    // =========================================================================

    (function injectWebformStyles() {
        if (document.getElementById('fle-webform-style')) return;
        var style = document.createElement('style');
        style.id  = 'fle-webform-style';
        style.textContent = [

            '#fle-pay-btn-wrapper[data-fle-state="hidden"] {',
            '  display:        none        !important;',
            '  visibility:     hidden      !important;',
            '  pointer-events: none        !important;',
            '  margin:         0           !important;',
            '  padding:        0           !important;',
            '  width:          0           !important;',
            '}',
            '#fle-pay-btn-wrapper[data-fle-state="visible"] {',
            '  display:        inline-flex !important;',
            '  visibility:     visible     !important;',
            '  pointer-events: auto        !important;',
            '}',

            '.web-form-footer,',
            '.form-footer,',
            '.page-actions {',
            '  display:         flex            !important;',
            '  flex-direction:  row             !important;',
            '  flex-wrap:       wrap            !important;',
            '  align-items:     center          !important;',
            '  justify-content: center          !important;',
            '  padding:         32px 24px 28px  !important;',
            '  margin:          0               !important;',
            '  gap:             0               !important;',
            '}',

            '#fle-pay-btn-wrapper {',
            '  display:     inline-flex !important;',
            '  align-items: center      !important;',
            '  margin:      0 8px       !important;',
            '  padding:     0           !important;',
            '}',

            '.web-form-footer .btn,',
            '.web-form-footer button,',
            '.page-actions .btn,',
            '.page-actions button,',
            '.form-footer .btn,',
            '.form-footer button {',
            '  all:             unset           !important;',
            '  box-sizing:      border-box      !important;',
            '  display:         inline-flex     !important;',
            '  align-items:     center          !important;',
            '  justify-content: center          !important;',
            '  white-space:     nowrap          !important;',
            '  font-family:     "Merriweather", Georgia, serif !important;',
            '  font-size:       13px            !important;',
            '  font-weight:     700             !important;',
            '  letter-spacing:  0.5px           !important;',
            '  padding:         10px 28px       !important;',
            '  border-radius:   5px             !important;',
            '  cursor:          pointer         !important;',
            '  min-height:      40px            !important;',
            '  line-height:     1               !important;',
            '  text-decoration: none            !important;',
            '  margin:          0 8px           !important;',
            '  transition:      background-color 0.2s ease, transform 0.1s ease, box-shadow 0.2s ease !important;',
            '}',

            '.web-form-footer .btn-primary,',
            '.web-form-footer button.btn-primary,',
            '.page-actions .btn-primary,',
            '.form-footer .btn-primary {',
            '  background-color: #8B0000                      !important;',
            '  color:            #ffffff                      !important;',
            '  border:           2px solid #8B0000            !important;',
            '  box-shadow:       0 2px 6px rgba(139,0,0,0.35) !important;',
            '}',
            '.web-form-footer .btn-primary:hover,',
            '.page-actions .btn-primary:hover,',
            '.form-footer .btn-primary:hover {',
            '  background-color: #6a0000                      !important;',
            '  border-color:     #6a0000                      !important;',
            '  transform:        translateY(-1px)              !important;',
            '  box-shadow:       0 4px 12px rgba(139,0,0,0.4) !important;',
            '  color:            #ffffff                      !important;',
            '}',
            '.web-form-footer .btn-primary:active,',
            '.page-actions .btn-primary:active {',
            '  transform:        translateY(0)   !important;',
            '  background-color: #5a0000         !important;',
            '}',

            '.web-form-footer .btn-default,',
            '.web-form-footer button.btn-default,',
            '.page-actions .btn-default,',
            '.form-footer .btn-default {',
            '  background-color: #ffffff           !important;',
            '  color:            #8B0000           !important;',
            '  border:           2px solid #8B0000 !important;',
            '  box-shadow:       none              !important;',
            '}',
            '.web-form-footer .btn-default:hover,',
            '.page-actions .btn-default:hover,',
            '.form-footer .btn-default:hover {',
            '  background-color: #fff4f4                      !important;',
            '  transform:        translateY(-1px)              !important;',
            '  box-shadow:       0 2px 8px rgba(139,0,0,0.15) !important;',
            '  color:            #8B0000                      !important;',
            '}',

            '.web-form-footer .btn-secondary,',
            '.web-form-footer button.btn-secondary,',
            '.page-actions .btn-secondary,',
            '.form-footer .btn-secondary {',
            '  background-color: #ffffff             !important;',
            '  color:            #555555             !important;',
            '  border:           2px solid #cccccc   !important;',
            '  box-shadow:       none                !important;',
            '}',
            '.web-form-footer .btn-secondary:hover,',
            '.page-actions .btn-secondary:hover,',
            '.form-footer .btn-secondary:hover {',
            '  background-color: #f5f5f5   !important;',
            '  border-color:     #aaaaaa   !important;',
            '  transform:        translateY(-1px) !important;',
            '  color:            #333333   !important;',
            '}',

            '.web-form-footer .btn-danger,',
            '.web-form-footer button.btn-danger,',
            '.page-actions .btn-danger,',
            '.form-footer .btn-danger {',
            '  background-color: #ffffff           !important;',
            '  color:            #cc0000           !important;',
            '  border:           2px solid #cc0000 !important;',
            '  box-shadow:       none              !important;',
            '}',
            '.web-form-footer .btn-danger:hover,',
            '.page-actions .btn-danger:hover,',
            '.form-footer .btn-danger:hover {',
            '  background-color: #fff0f0                      !important;',
            '  transform:        translateY(-1px)              !important;',
            '  box-shadow:       0 2px 8px rgba(204,0,0,0.15) !important;',
            '  color:            #aa0000                      !important;',
            '}',

            '.fle-check-row {',
            '  display:        flex        !important;',
            '  flex-direction: row         !important;',
            '  align-items:    center      !important;',
            '  flex-wrap:      nowrap      !important;',
            '  gap:            8px         !important;',
            '  margin:         4px 0       !important;',
            '  padding:        0           !important;',
            '  cursor:         pointer;',
            '}',
            '.fle-check-row input[type="checkbox"] {',
            '  display:        inline-block !important;',
            '  flex-shrink:    0            !important;',
            '  width:          15px         !important;',
            '  height:         15px         !important;',
            '  min-width:      15px         !important;',
            '  min-height:     15px         !important;',
            '  margin:         0            !important;',
            '  padding:        0            !important;',
            '  float:          none         !important;',
            '  position:       relative     !important;',
            '  top:            0            !important;',
            '  vertical-align: middle       !important;',
            '  cursor:         pointer;',
            '}',
            '.fle-check-row .fle-check-label {',
            '  display:        inline   !important;',
            '  vertical-align: middle   !important;',
            '  line-height:    1.5      !important;',
            '  margin:         0        !important;',
            '  padding:        0        !important;',
            '  font-family:    inherit  !important;',
            '  font-size:      inherit  !important;',
            '  color:          inherit  !important;',
            '  cursor:         pointer;',
            '}',

            '[data-fieldname="i_hereby_consent_to_this_declaration"] .fle-chk-original-hidden {',
            '  display: none !important;',
            '}'

        ].join('\n');
        (document.head || document.documentElement).appendChild(style);
    })();

    // =========================================================================
    //  USER IDENTITY
    // =========================================================================

    function getUserEmail() {
        var params   = new URLSearchParams(window.location.search);
        var urlEmail = params.get('email_address') || params.get('email') || '';
        if (urlEmail && urlEmail.indexOf('@') !== -1) return urlEmail.toLowerCase().trim();

        var emailWrapper = document.querySelector('[data-fieldname="email_address"]');
        if (emailWrapper) {
            var emailInp = emailWrapper.querySelector('input.input-with-feedback');
            if (emailInp && emailInp.value && emailInp.value.indexOf('@') !== -1) {
                return emailInp.value.toLowerCase().trim();
            }
        }

        if (window.frappe && frappe.session && frappe.session.user &&
            frappe.session.user !== 'Guest') {
            return frappe.session.user.toLowerCase().trim();
        }
        return '';
    }

    function getDraftKey() {
        var email = getUserEmail();
        if (!email) return null;
        return DRAFT_KEY_PREFIX + email.replace(/[^a-z0-9@._-]/g, '_');
    }

    // =========================================================================
    //  FIELD TYPE MAP
    // =========================================================================

    var TYPED_FIELDS = {
        'candidate_gender'                    : 'select',
        'candidate_state'                     : 'select',
        'where_did_you_hear'                  : 'select',
        'last_class_attended'                 : 'select',
        'latest_board_attended'               : 'select',
        'year_of_passing'                     : 'select',
        'relationship_with_the_candidate'     : 'select',
        'candidate_nationality'               : 'link',
        'i_hereby_consent_to_this_declaration': 'check'
    };

    var SKIP_FIELDS = { '__newname': true, 'amended_from': true };

    // =========================================================================
    //  REQUIRED FIELDS FOR "PROCEED TO PAY"
    // =========================================================================

    var REQUIRED_FOR_PAY = [
        'email_address',
        'candidate_name',
        'candidate_dob',
        'candidate_gender',
        'where_did_you_hear',
        'last_class_attended',
        'latest_board_attended',
        'year_of_passing'
    ];

    // =========================================================================
    //  STORAGE
    // =========================================================================

    var Store = {
        save: function (data) {
            var key = getDraftKey();
            if (!key) { console.warn('[Draft] No user key — cannot save.'); return false; }
            try { localStorage.setItem(key, JSON.stringify(data)); return true; }
            catch (e) { console.error('[Draft] save error:', e); return false; }
        },
        load: function () {
            var key = getDraftKey();
            if (!key) return null;
            try {
                var r = localStorage.getItem(key);
                return r ? JSON.parse(r) : null;
            } catch (e) { return null; }
        }
    };

    // =========================================================================
    //  FIELD DISCOVERY
    // =========================================================================

    function discoverFields() {
        var result = [], seen = {};
        document.querySelectorAll('[data-fieldname]').forEach(function (wrapper) {
            var fn = wrapper.getAttribute('data-fieldname');
            if (!fn || seen[fn] || SKIP_FIELDS[fn]) return;

            var explicitType = TYPED_FIELDS[fn];
            var chk = wrapper.querySelector('input[type="checkbox"]');
            if (!explicitType && chk) explicitType = 'check';

            var hasInput = wrapper.querySelector(
                'input.input-with-feedback, select, textarea, input[type="checkbox"]'
            );
            if (!hasInput) return;

            seen[fn] = true;
            result.push({ fieldname: fn, type: explicitType || 'text' });
        });
        return result;
    }

    // =========================================================================
    //  READ FIELD
    // =========================================================================

    function readSelectField(wrapper) {
        var sel = wrapper.querySelector('select');
        if (sel && sel.value && sel.value.trim()) return sel.value.trim();
        var inp = wrapper.querySelector('input.input-with-feedback');
        if (inp && inp.value && inp.value.trim()) return inp.value.trim();
        var ldi = wrapper.querySelector('.like-disabled-input');
        if (ldi && ldi.textContent && ldi.textContent.trim()) return ldi.textContent.trim();
        var optSel = wrapper.querySelector('[data-label]');
        if (optSel) {
            var lbl = optSel.getAttribute('data-label') || '';
            if (lbl.trim()) return lbl.trim();
        }
        try {
            if (window.frappe && frappe.web_form && frappe.web_form.doc) {
                var fn  = wrapper.getAttribute('data-fieldname');
                var dv  = frappe.web_form.doc[fn];
                if (dv && dv.toString().trim()) return dv.toString().trim();
            }
        } catch (e) { /* ignore */ }
        return '';
    }

    function readField(cfg) {
        var wrapper = document.querySelector('[data-fieldname="' + cfg.fieldname + '"]');
        if (!wrapper) return '';

        if (cfg.type === 'check') {
            var chk = wrapper.querySelector('input[type="checkbox"]');
            return chk ? (chk.checked ? '1' : '0') : '';
        }
        if (cfg.type === 'select') return readSelectField(wrapper);
        if (cfg.type === 'link') {
            var inp2 = wrapper.querySelector('input.input-with-feedback');
            if (inp2 && inp2.value && inp2.value.trim()) return inp2.value.trim();
            try {
                if (window.frappe && frappe.web_form && frappe.web_form.doc) {
                    var dv2 = frappe.web_form.doc[cfg.fieldname];
                    if (dv2 && dv2.toString().trim()) return dv2.toString().trim();
                }
            } catch (e) { /* ignore */ }
            return '';
        }
        var inp3 = wrapper.querySelector('input.input-with-feedback');
        if (inp3 && inp3.value && inp3.value.trim()) return inp3.value.trim();
        var ta = wrapper.querySelector('textarea');
        if (ta && ta.value && ta.value.trim()) return ta.value.trim();
        return '';
    }

    // =========================================================================
    //  NATIVE VALUE SETTER
    //  Uses the browser's native input descriptor so React/Vue/Frappe
    //  internal state tracking picks up the change correctly.
    // =========================================================================

    function nativeSet(inp, val) {
        try {
            var desc = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value');
            if (desc && desc.set) { desc.set.call(inp, val); return; }
        } catch (e) { /* fall through */ }
        inp.value = val;
    }

    // =========================================================================
    //  EVENT HELPERS
    // =========================================================================

    // Full event fire — for live user interaction paths only
    function fire(el, types) {
        types.forEach(function (t) {
            el.dispatchEvent(new Event(t, { bubbles: true }));
        });
    }

    // Change-only fire — safe for restore; does NOT open Frappe autocomplete
    function fireChange(el) {
        el.dispatchEvent(new Event('change', { bubbles: true }));
    }

    // =========================================================================
    //  WRITE FIELD
    //
    //  Two modes via `isRestore` flag:
    //
    //  isRestore = true  → RESTORE PATH
    //    • <select> fields: set selectedIndex directly, fire 'change' only.
    //      No 'input' event = no autocomplete overlay. No blur() call.
    //    • Link (<input>) fields: set value via nativeSet, fire 'change' only.
    //      No inp.blur() — that was stealing focus and clearing the field.
    //      Dropdown suppression is done ONLY on the awesomplete <ul>, not the
    //      input itself, so the field keeps its value.
    //    • Text fields: direct value assignment, no events needed for restore.
    //
    //  isRestore = false/undefined → LIVE PATH
    //    • Fires both 'input' and 'change' so Frappe model stays in sync.
    // =========================================================================

    function writeField(cfg, val, isRestore) {
        if (val === '' || val === null || val === undefined) return false;
        var wrapper = document.querySelector('[data-fieldname="' + cfg.fieldname + '"]');
        if (!wrapper) return false;
        if (cfg.type === 'check')  return writeCheck(wrapper, val);
        if (cfg.type === 'select') return writeSelect(wrapper, val, isRestore);
        if (cfg.type === 'link')   return writeLink(wrapper, val, isRestore);
        return writeText(wrapper, val, isRestore);
    }

    function writeCheck(wrapper, val) {
        var chk = wrapper.querySelector('input[type="checkbox"]');
        if (!chk) return false;
        var shouldCheck = (val === '1' || val === true || val === 'true');
        if (chk.checked !== shouldCheck) { chk.checked = shouldCheck; fireChange(chk); }
        return true;
    }

    function writeSelect(wrapper, val, isRestore) {
        var sel = wrapper.querySelector('select');
        var matched = false;

        if (sel) {
            for (var i = 0; i < sel.options.length; i++) {
                var o = sel.options[i];
                if (o.value.trim().toLowerCase() === val.toLowerCase() ||
                    o.text.trim().toLowerCase()  === val.toLowerCase()) {
                    sel.selectedIndex = i;
                    matched = true;
                    break;
                }
            }
            if (matched) {
                // Fire 'change' for both paths — safe, does not open dropdowns
                fireChange(sel);
            }
        }

        // Some Frappe Select fields also render a backing <input>
        var inp = wrapper.querySelector('input.input-with-feedback');
        if (inp) {
            nativeSet(inp, val);
            if (isRestore) {
                // Restore: 'change' only — no autocomplete trigger, no blur
                fireChange(inp);
            } else {
                fire(inp, ['input', 'change']);
            }
        }

        return matched || !!inp;
    }

    function writeLink(wrapper, val, isRestore) {
        var inp = wrapper.querySelector('input.input-with-feedback');
        if (!inp) return false;

        nativeSet(inp, val);

        if (isRestore) {
            // Restore: 'change' only — prevents autocomplete overlay
            // Do NOT call inp.blur() here — it was clearing the field value
            // by triggering Frappe's blur handler which resets unverified links.
            // Instead only hide the awesomplete suggestion <ul> if it opened.
            fireChange(inp);
            hideAwesomplete(wrapper);
            setTimeout(function () { hideAwesomplete(wrapper); }, 100);
            setTimeout(function () { hideAwesomplete(wrapper); }, 300);
        } else {
            fire(inp, ['input', 'change']);
        }

        return true;
    }

    function writeText(wrapper, val, isRestore) {
        var inp = wrapper.querySelector('input.input-with-feedback');
        if (inp) {
            nativeSet(inp, val);
            if (!isRestore) fire(inp, ['input', 'change']);
            else fireChange(inp);
            return true;
        }
        var ta = wrapper.querySelector('textarea');
        if (ta) {
            ta.value = val;
            if (!isRestore) fire(ta, ['input', 'change']);
            else fireChange(ta);
            return true;
        }
        return false;
    }

    // =========================================================================
    //  DROPDOWN / AWESOMPLETE SUPPRESSION
    //
    //  hideAwesomplete(wrapper)
    //    → Hides ONLY the suggestion <ul> inside the given field wrapper.
    //    → Does NOT call inp.blur() — that was the root cause of the
    //      Nationality field appearing empty (Frappe's blur handler
    //      clears Link fields whose value hasn't been "confirmed" via
    //      the autocomplete selection flow).
    //    → Does NOT touch any other field's dropdowns.
    //
    //  window._fle_killDropdownsGlobal — console debug only, never called here.
    // =========================================================================

    function hideAwesomplete(wrapper) {
        if (!wrapper) return;
        // Only hide the suggestion list popup, never the input itself
        wrapper.querySelectorAll(
            '.awesomplete > ul, ul[role="listbox"], .link-field-popup'
        ).forEach(function (ul) {
            ul.style.setProperty('display',    'none',   'important');
            ul.style.setProperty('visibility', 'hidden', 'important');
            ul.setAttribute('aria-hidden', 'true');
        });
        var aw = wrapper.querySelector('.awesomplete');
        if (aw) aw.classList.remove('open');
    }

    window._fle_killDropdownsGlobal = function () {
        document.querySelectorAll(
            '.dropdown-menu, .awesomplete > ul, ul.awesomplete, .link-field-popup'
        ).forEach(function (dd) {
            dd.style.display    = 'none';
            dd.style.visibility = 'hidden';
            dd.setAttribute('aria-hidden', 'true');
        });
        document.querySelectorAll('.awesomplete').forEach(function (aw) {
            aw.classList.remove('open');
        });
    };

    // =========================================================================
    //  VERIFY
    // =========================================================================

    function verifyField(cfg, expected) {
        if (cfg.type === 'check') return true;
        var actual = readField(cfg);
        if (!actual) return false;
        return actual.toLowerCase() === expected.toLowerCase();
    }

    // =========================================================================
    //  SAVE DRAFT
    // =========================================================================

    function saveDraft(silent) {
        var fields    = discoverFields();
        var userEmail = getUserEmail();
        var draft = {
            __saved_at  : new Date().toLocaleString(),
            __user_email: userEmail,
            __fields    : []
        };

        fields.forEach(function (cfg) {
            var v = readField(cfg);
            draft[cfg.fieldname] = v;
            draft.__fields.push({ fieldname: cfg.fieldname, type: cfg.type });
            if (v) console.log('[Draft] Save:', cfg.fieldname, '(' + cfg.type + ') =', JSON.stringify(v));
        });

        fields.forEach(function (cfg) {
            if (cfg.type === 'check' && draft[cfg.fieldname] === '') draft[cfg.fieldname] = '0';
        });

        var ok = Store.save(draft);
        if (!silent) {
            showToast(
                ok ? '💾 Draft saved at ' + draft.__saved_at
                   : '❌ Could not save — storage unavailable',
                ok ? '#16a34a' : '#dc2626'
            );
        }
        console.log('[Draft] Saved ' + fields.length + ' fields (ok=' + ok + ')');
    }

    // =========================================================================
    //  AUTO-SAVE
    // =========================================================================

    var _autoTimer = null;
    function scheduleAutoSave() {
        clearTimeout(_autoTimer);
        _autoTimer = setTimeout(function () { saveDraft(true); }, 1500);
    }

    // =========================================================================
    //  RESTORE DRAFT
    // =========================================================================

    function restoreDraft() {
        var draft = Store.load();
        if (!draft) return;

        var currentEmail = getUserEmail();
        if (currentEmail && draft.__user_email &&
            draft.__user_email.toLowerCase() !== currentEmail.toLowerCase()) {
            console.warn('[Draft] Draft belongs to', draft.__user_email,
                         '— current user is', currentEmail, '— skipping restore.');
            return;
        }

        var savedFields = (draft.__fields || []).slice();
        var seen = {};
        savedFields.forEach(function (f) { seen[f.fieldname] = true; });
        Object.keys(TYPED_FIELDS).forEach(function (fn) {
            if (!seen[fn] && draft[fn] !== undefined) {
                savedFields.push({ fieldname: fn, type: TYPED_FIELDS[fn] });
            }
        });

        var pending = savedFields.filter(function (cfg) {
            var v = draft[cfg.fieldname];
            if (cfg.type === 'check') return v === '1' || v === '0';
            return !!v;
        });

        if (!pending.length) return;

        console.log('[Draft] Restore pending:', pending.map(function (f) { return f.fieldname; }));

        var attempts = 0, MAX = 80, toastShown = false;

        function attempt() {
            attempts++;
            var still = [];

            pending.forEach(function (cfg) {
                var wrapper = document.querySelector('[data-fieldname="' + cfg.fieldname + '"]');
                if (!wrapper) { still.push(cfg); return; }

                // For select fields wait until <select> has options loaded
                if (cfg.type === 'select') {
                    var sel = wrapper.querySelector('select');
                    var inp = wrapper.querySelector('input.input-with-feedback');
                    if (!((sel && sel.options.length > 1) || inp)) {
                        still.push(cfg); return;
                    }
                }

                // isRestore = true: safe restore — no 'input' events, no blur()
                writeField(cfg, draft[cfg.fieldname], true);

                if (!verifyField(cfg, draft[cfg.fieldname])) {
                    still.push(cfg);
                } else {
                    console.log('[Draft] ✅ Restored:', cfg.fieldname, '->', draft[cfg.fieldname]);
                }
            });

            pending = still;

            if (pending.length === 0) {
                onDone(draft, toastShown); toastShown = true;
            } else if (attempts < MAX) {
                setTimeout(attempt, 100);
            } else {
                console.warn('[Draft] Timed out restoring:', pending.map(function (f) { return f.fieldname; }));
                if (!toastShown) { onDone(draft, false); toastShown = true; }
            }
        }

        attempt();
    }

    function onDone(draft, alreadyShown) {
        setTimeout(updatePayBtn, 100);
        if (!alreadyShown && draft.__saved_at) {
            showToast('📋 Draft restored from ' + draft.__saved_at, '#2563eb');
        }
    }

    // =========================================================================
    //  PROCEED TO PAY — WRAPPER APPROACH
    // =========================================================================

    function getPayBtn() {
        var candidates = Array.prototype.slice.call(document.querySelectorAll(
            'button.submit-btn, button.btn-primary, button[data-action="submit"], ' +
            'button[type="submit"], .web-form-footer button, .page-actions button, ' +
            '.form-footer button'
        ));
        for (var i = 0; i < candidates.length; i++) {
            var txt = (candidates[i].textContent || '').toLowerCase().trim();
            if (txt.indexOf('pay')     !== -1 ||
                txt.indexOf('proceed') !== -1 ||
                txt.indexOf('submit')  !== -1) {
                return candidates[i];
            }
        }
        return document.querySelector(
            '.web-form-footer button.btn-primary, .page-actions button.btn-primary, ' +
            '.form-footer button.btn-primary, button.btn-primary.submit-btn'
        );
    }

    function getWrapper() {
        return document.getElementById('fle-pay-btn-wrapper');
    }

    function wrapPayBtn() {
        var btn = getPayBtn();
        if (!btn) return null;
        var existingWrapper = getWrapper();
        if (existingWrapper && existingWrapper.contains(btn)) return existingWrapper;
        var wrapper = document.createElement('span');
        wrapper.id  = 'fle-pay-btn-wrapper';
        wrapper.setAttribute('data-fle-state', 'hidden');
        wrapper.style.cssText = 'display:inline-flex;align-items:center;';
        btn.parentNode.insertBefore(wrapper, btn);
        wrapper.appendChild(btn);
        console.log('[Pay] Button wrapped in #fle-pay-btn-wrapper');
        return wrapper;
    }

    function getFieldValue(fn) {
        var type = TYPED_FIELDS[fn] || 'text';
        var val  = readField({ fieldname: fn, type: type });
        if (val && val.trim()) return val.trim();
        try {
            if (window.frappe && frappe.web_form && frappe.web_form.doc) {
                var dv = frappe.web_form.doc[fn];
                if (dv && dv.toString().trim()) return dv.toString().trim();
            }
        } catch (e) { /* ignore */ }
        return '';
    }

    var _lastMissingLog = 0;

    function allFilled() {
        var missing = [];
        REQUIRED_FOR_PAY.forEach(function (fn) {
            if (!getFieldValue(fn)) missing.push(fn);
        });
        if (missing.length) {
            var now = Date.now();
            if (now - _lastMissingLog > 2000) {
                console.log('[Pay] Missing:', missing);
                _lastMissingLog = now;
            }
        }
        return missing.length === 0;
    }

    function updatePayBtn() {
        var wrapper = wrapPayBtn();
        if (!wrapper) return;
        if (allFilled()) {
            wrapper.setAttribute('data-fle-state', 'visible');
            console.log('[Pay] ✅ All filled — button VISIBLE');
        } else {
            wrapper.setAttribute('data-fle-state', 'hidden');
        }
    }

    function ensurePayBtnHidden() {
        var wrapper = wrapPayBtn();
        if (wrapper && !wrapper.__fle_boot_hidden) {
            wrapper.__fle_boot_hidden = true;
            wrapper.setAttribute('data-fle-state', 'hidden');
            console.log('[Pay] Button wrapped and hidden on boot.');
        }
    }

    var _payObserver = new MutationObserver(function (mutations) {
        var hasNew = mutations.some(function (m) { return m.addedNodes.length > 0; });
        if (!hasNew) return;
        ensurePayBtnHidden();
        updatePayBtn();
    });
    _payObserver.observe(document.body || document.documentElement, {
        childList: true,
        subtree  : true
    });

    var _rafBoot = true;
    (function rafBootLoop() {
        if (!_rafBoot) return;
        ensurePayBtnHidden();
        updatePayBtn();
        requestAnimationFrame(rafBootLoop);
    })();
    setTimeout(function () { _rafBoot = false; }, 2000);

    // =========================================================================
    //  APPLY FOOTER BUTTON STYLES
    // =========================================================================

    function applyFooterButtonStyles() {
