                btn.style.setProperty('box-shadow',       'none',              'important');
            } else if (isDiscardBtn) {
                btn.style.setProperty('background-color', '#ffffff',           'important');
                btn.style.setProperty('color',            '#555555',           'important');
                btn.style.setProperty('border',           '2px solid #cccccc', 'important');
                btn.style.setProperty('box-shadow',       'none',              'important');
            } else {
                btn.style.setProperty('background-color', '#ffffff',           'important');
                btn.style.setProperty('color',            '#8B0000',           'important');
                btn.style.setProperty('border',           '2px solid #8B0000', 'important');
                btn.style.setProperty('box-shadow',       'none',              'important');
            }
        });

        var payWrapper = document.getElementById('fle-pay-btn-wrapper');
        if (payWrapper) {
            payWrapper.style.setProperty('display',     'inline-flex', 'important');
            payWrapper.style.setProperty('align-items', 'center',      'important');
            payWrapper.style.setProperty('margin',      '0 8px',       'important');
            payWrapper.style.setProperty('padding',     '0',           'important');
