        document.querySelectorAll('.web-form-footer, .page-actions, .form-footer')
            .forEach(function (footer) {
                footer.style.setProperty('display',         'flex',             'important');
                footer.style.setProperty('flex-direction',  'row',              'important');
                footer.style.setProperty('flex-wrap',       'wrap',             'important');
                footer.style.setProperty('gap',             '0',                'important');
                footer.style.setProperty('align-items',     'center',           'important');
                footer.style.setProperty('justify-content', 'center',           'important');
                footer.style.setProperty('padding',         '32px 24px 28px',   'important');
                footer.style.setProperty('margin',          '0',                'important');
            });
    }

    // =========================================================================
    //  TOAST
    // =========================================================================

    function showToast(msg, bg) {
        $('#fle-draft-toast').remove();
        $('<div id="fle-draft-toast"></div>').text(msg).css({
            position    : 'fixed',
            bottom      : '28px',
            right       : '28px',
            background  : bg || '#16a34a',
            color       : '#fff',
            padding     : '11px 20px',
            borderRadius: '7px',
            fontSize    : '13px',
            fontWeight  : '600',
            fontFamily  : "'Merriweather', Georgia, serif",
            boxShadow   : '0 4px 16px rgba(0,0,0,0.18)',
            zIndex      : 999999,
            opacity     : 0,
            maxWidth    : '360px',
            lineHeight  : '1.5'
        }).appendTo('body').animate({ opacity: 1 }, 250);
        setTimeout(function () {
            $('#fle-draft-toast').animate({ opacity: 0 }, 350, function () {
                $(this).remove();
            });
        }, 3500);
    }

    // =========================================================================
    //  DOB VALIDATION
    // =========================================================================

    function isFutureOrToday(val) {
        if (!val) return false;
        var p = val.split('-');
        if (p.length !== 3) return false;
        var d = p[0].length === 4
            ? new Date(+p[0], +p[1] - 1, +p[2])
            : new Date(+p[2], +p[0] - 1, +p[1]);
        if (!d || isNaN(d.getTime())) return false;
        var t = new Date();
        t.setHours(0, 0, 0, 0);
        return d >= t;
    }

    var dobAlertShown = false;

    function showDOBError() {
        if (dobAlertShown) return;
        dobAlertShown = true;
        $('#dob-error-msg').remove();
        $('[data-fieldname="candidate_dob"]').first().after(
            '<div id="dob-error-msg" style="' +
            'background:#fff2f2;border:1px solid #e74c3c;border-left:4px solid #e74c3c;' +
            'color:#c0392b;padding:10px 14px;border-radius:4px;margin-top:6px;' +
            'font-size:13px;font-weight:500;font-family:Merriweather,Georgia,serif;' +
            'display:flex;align-items:center;gap:8px;">' +
            '<span style="font-size:16px;">⚠️</span>' +
            'Date of Birth cannot be today or a future date.</div>'
        );
        setTimeout(function () {
            $('#dob-error-msg').fadeOut(400, function () {
                $(this).remove();
                dobAlertShown = false;
            });
        }, 4000);
    }

    function clearDOB(inp) {
        inp.value = '';
        $(inp).val('').trigger('change');
        fire(inp, ['input', 'change']);
        setTimeout(updatePayBtn, 100);
    }

    function restrictDOB() {
        var inp = document.querySelector(
            '[data-fieldname="candidate_dob"] input.input-with-feedback'
        );
        if (!inp || inp.__dob) return;
        inp.__dob = true;
        inp.addEventListener('change', function () {
            if (isFutureOrToday(inp.value)) { clearDOB(inp); showDOBError(); }
        });
        inp.addEventListener('blur', function () {
            if (isFutureOrToday(inp.value)) { clearDOB(inp); showDOBError(); }
        });
        inp.addEventListener('keyup', function () {
            if (inp.value.length >= 8 && isFutureOrToday(inp.value)) {
                clearDOB(inp); showDOBError();
            }
        });
    }

    // =========================================================================
    //  ATTACH INPUT LISTENERS (live user interaction only)
    // =========================================================================

    function attach() {
        document.querySelectorAll(
            '[data-fieldname] input, [data-fieldname] select, [data-fieldname] textarea'
        ).forEach(function (el) {
            if (el.__b) return;
            el.__b = true;
            el.addEventListener('input',  function () { updatePayBtn(); scheduleAutoSave(); });
            el.addEventListener('change', function () { updatePayBtn(); scheduleAutoSave(); });
            el.addEventListener('blur',   function () { updatePayBtn(); scheduleAutoSave(); });
        });
    }

    // =========================================================================
    //  CHECKBOX ALIGNMENT — DOM RECONSTRUCTION
    // =========================================================================

    function fixCheckboxAlignment() {
        var FIELD   = 'i_hereby_consent_to_this_declaration';
        var wrapper = document.querySelector('[data-fieldname="' + FIELD + '"]');
        if (!wrapper) return;

        var chk = wrapper.querySelector('input[type="checkbox"]');
        if (!chk) return;

        if (wrapper.__chk_rebuilt && document.contains(wrapper.__chk_rebuilt)) return;

        var labelText = '';
        var labelEl   = null;

        var parentLabel = chk.closest('label');
        if (parentLabel) {
            var labelClone = parentLabel.cloneNode(true);
            var cloneChk   = labelClone.querySelector('input[type="checkbox"]');
            if (cloneChk) cloneChk.parentNode.removeChild(cloneChk);
            labelText = labelClone.textContent.trim();
            labelEl   = parentLabel;
        }

        if (!labelText) {
            var searchRoot = chk.parentNode || wrapper;
            var allEls = Array.prototype.slice.call(
                searchRoot.querySelectorAll('label, .label-area, .static-area, span, div')
            );
            for (var i = 0; i < allEls.length; i++) {
                var el  = allEls[i];
                var txt = el.textContent.trim();
                if (txt && (txt.toLowerCase().indexOf('consent') !== -1 ||
                            txt.toLowerCase().indexOf('declaration') !== -1)) {
                    labelText = txt;
                    labelEl   = el;
                    break;
                }
            }
        }

        if (!labelText) {
            var chkParent = chk.parentNode;
            var siblings  = chkParent ? Array.prototype.slice.call(chkParent.childNodes) : [];
            for (var j = 0; j < siblings.length; j++) {
                var sib = siblings[j];
                if (sib === chk) continue;
                var sibText = (sib.textContent || '').trim();
                if (sibText) { labelText = sibText; labelEl = sib; break; }
            }
        }

        var row       = document.createElement('label');
        row.className = 'fle-check-row';
        row.htmlFor   = chk.id || '';

        var chkParentNode = chk.parentNode;
        row.appendChild(chk);

        var textSpan         = document.createElement('span');
        textSpan.className   = 'fle-check-label';
        textSpan.textContent = labelText || 'I Hereby Consent To This Declaration.';
        row.appendChild(textSpan);

        if (labelEl && labelEl !== chk) {
            labelEl.classList.add('fle-chk-original-hidden');
            labelEl.style.setProperty('display', 'none', 'important');
        }

        if (chkParentNode && chkParentNode !== wrapper &&
            chkParentNode.textContent.trim() === '' &&
            !chkParentNode.querySelector('input, select, textarea')) {
            chkParentNode.style.setProperty('display', 'none', 'important');
        }

        if (wrapper.firstChild) {
            wrapper.insertBefore(row, wrapper.firstChild);
        } else {
            wrapper.appendChild(row);
        }

        wrapper.__chk_rebuilt = row;

        row.addEventListener('click', function () {
            fire(chk, ['change']);
            scheduleAutoSave();
        });

        console.log('[FLE] ✅ Checkbox reconstructed. Label: "' + labelText + '"');
    }

    // =========================================================================
    //  INJECT SAVE AS DRAFT BUTTON
    // =========================================================================

    function injectDraftBtn() {
        var existing = document.getElementById('fle-save-draft-btn');
        if (existing && document.body && document.body.contains(existing)) return;

        var $footer = $('.web-form-footer, .page-actions, .form-footer').first();
        if (!$footer.length) return;

        var $btn = $('<button type="button" id="fle-save-draft-btn" class="btn btn-default"></button>')
            .html(
                '<svg xmlns="http://www.w3.org/2000/svg" width="13" height="13" ' +
                'viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" ' +
                'stroke-linecap="round" stroke-linejoin="round" ' +
                'style="margin-right:6px;vertical-align:middle;">' +
                '<path d="M19 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11l5 5v11a2 2 0 0 1-2 2z"></path>' +
                '<polyline points="17 21 17 13 7 13 7 21"></polyline>' +
                '<polyline points="7 3 7 8 15 8"></polyline>' +
                '</svg>Save As Draft'
            )
            .on('click', function (e) {
                e.preventDefault();
                e.stopPropagation();
                saveDraft(false);
            });

        $footer.prepend($btn);
        console.log('[Draft] Save As Draft button injected.');
    }

    // =========================================================================
    //  DEBUG HELPER — run checkFields() in browser console
    // =========================================================================

    window.checkFields = function () {
        console.log('===== LIVE FIELD SCAN =====');
        discoverFields().forEach(function (cfg) {
            var v = readField(cfg);
            console.log(v ? '✅' : '❌', cfg.fieldname, '(' + cfg.type + ') ->', JSON.stringify(v));
        });
        console.log('--- Required for Pay ---');
        REQUIRED_FOR_PAY.forEach(function (fn) {
            var v = getFieldValue(fn);
            console.log(v ? '✅' : '❌', fn, '->', JSON.stringify(v));
        });
        console.log('allFilled    ->', allFilled());
        console.log('Pay button   ->', getPayBtn());
        console.log('Wrapper      ->', getWrapper());
        console.log('Current user ->', getUserEmail());
        console.log('Draft key    ->', getDraftKey());
        console.log('Stored draft ->', Store.load());
        console.log('===========================');
    };

    // =========================================================================
    //  BOOT SEQUENCE
    // =========================================================================

    console.log('[FLE] webform.js loaded');

    ensurePayBtnHidden();
    restoreDraft();

    setInterval(function () {
        ensurePayBtnHidden();
        restrictDOB();
        attach();
        updatePayBtn();
        injectDraftBtn();
        fixCheckboxAlignment();
        applyFooterButtonStyles();

        var d = document.querySelector('[data-fieldname="candidate_dob"] input.input-with-feedback');
        if (d && d.value && isFutureOrToday(d.value)) { clearDOB(d); showDOBError(); }
    }, 300);

    setTimeout(function () {
        restrictDOB();
        attach();
        updatePayBtn();
        injectDraftBtn();
        fixCheckboxAlignment();
        applyFooterButtonStyles();
        console.log('[FLE] Boot complete. Fields:',
            discoverFields().map(function (f) { return f.fieldname; }));
        console.log('[FLE] allFilled:', allFilled());
        console.log('[FLE] Wrapper state:',
            getWrapper() ? getWrapper().getAttribute('data-fle-state') : 'no wrapper');
    }, 2000);

});

